    @Test
    void tourismTaxChargesTheFeePerGuestPerNightOnPaidReservationsStartingInTheMonth() {
        Guest guest = new Guest("Bruno Lima", "bruno@example.com", "987.654.321-00");
        Reservation family = service.create(new NewReservation(
                202, guest, LocalDate.parse("2027-04-10"), LocalDate.parse("2027-04-13"), 2, RatePlan.STANDARD));
        service.confirm(family.id());

        String csv = new TourismTaxReport(store, new BigDecimal("4.50")).generate(YearMonth.of(2027, 4));

        // the unpaid and the cancelled reservations pay no tax; the March one starts in March
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-04
                reservation,room,check_in,check_out,guests,nights,tax
                1,201,2027-04-01,2027-04-03,1,2,9.00
                3,301,2027-04-02,2027-04-04,1,2,9.00
                6,202,2027-04-10,2027-04-13,2,3,27.00
                total,45.00
                """, csv);
    }

    @Test
    void anEmptyMonthHasNoTourismTax() {
        String csv = new TourismTaxReport(store, new BigDecimal("4.50")).generate(YearMonth.of(2027, 6));

        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-06
                reservation,room,check_in,check_out,guests,nights,tax
                total,0.00
                """, csv);
    }

    @Test
    void ratePlansHaveOneLineEachEvenWithoutReservations() {
        String csv = new RatePlanReport(store).generate(YearMonth.of(2027, 4));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-04
                rate_plan,reservations,amount
                STANDARD,2,1939.60
                NON_REFUNDABLE,0,0.00
                total,2,1939.60
                """, csv);
    }

    @Test
    void ratePlansCountACancelledNonRefundableReservation() {
        Reservation may = book(101, "2027-05-10", "2027-05-11", RatePlan.NON_REFUNDABLE);
        service.confirm(may.id());
        service.cancel(may.id());

        String csv = new RatePlanReport(store).generate(YearMonth.of(2027, 5));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-05
                rate_plan,reservations,amount
                STANDARD,0,0.00
                NON_REFUNDABLE,1,212.42
                total,1,212.42
                """, csv);
    }
}
